import re
import os


def task_func(request):
    def build_response(status_line, body="", content_length=None):
        lines = [f"HTTP/1.1 {status_line}"]
        if content_length is not None:
            lines.append(f"Content-Length: {content_length}")
        return "\n".join(lines) + "\n\n" + body

    if not isinstance(request, str) or not request.strip():
        return build_response("400 Bad Request", "Invalid request")

    request_line = request.splitlines()[0].strip()
    match = re.fullmatch(r"GET\s+(\S+)\s+HTTP/\d+\.\d+", request_line)
    if not match:
        return build_response("400 Bad Request", "Invalid request")

    target = match.group(1)

    # Reject obvious absolute-URI targets and strip query/fragment parts.
    if "://" in target:
        return build_response("400 Bad Request", "Invalid request")
    target = target.split("?", 1)[0].split("#", 1)[0]

    relative_path = target.lstrip("/")
    if not relative_path:
        return build_response("400 Bad Request", "Invalid request")

    normalized_path = os.path.normpath(relative_path)

    if (
        normalized_path in ("", ".")
        or normalized_path.startswith("..")
        or os.path.isabs(normalized_path)
    ):
        return build_response("400 Bad Request", "Invalid request")

    root_dir = os.path.abspath(os.getcwd())
    file_path = os.path.abspath(os.path.join(root_dir, normalized_path))

    try:
        if os.path.commonpath([root_dir, file_path]) != root_dir:
            return build_response("400 Bad Request", "Invalid request")
    except ValueError:
        return build_response("400 Bad Request", "Invalid request")

    if not os.path.isfile(file_path):
        return build_response("404 Not Found", "File not found")

    try:
        with open(file_path, "rb") as f:
            data = f.read()
        try:
            content = data.decode("utf-8")
        except UnicodeDecodeError:
            content = data.decode("latin-1")
    except OSError:
        return build_response("500 Internal Server Error", "Internal server error")

    return build_response("200 OK", content, content_length=len(data))

