import base64
import hashlib
import os


def task_func(password, SALT_LENGTH=32) -> tuple[bytes, bytes]:
    if password is None:
        raise ValueError("password cannot be None")

    if not isinstance(SALT_LENGTH, int) or SALT_LENGTH <= 0:
        raise ValueError("SALT_LENGTH must be a positive integer")

    if isinstance(password, str):
        if password == "":
            raise ValueError("password cannot be empty")
        password_bytes = password.encode("utf-8")
    elif isinstance(password, (bytes, bytearray, memoryview)):
        password_bytes = bytes(password)
        if len(password_bytes) == 0:
            raise ValueError("password cannot be empty")
    else:
        raise TypeError("password must be a string or bytes-like object")

    salt = os.urandom(SALT_LENGTH)
    hashed_password = hashlib.pbkdf2_hmac(
        "sha256",
        password_bytes,
        salt,
        100000,
    )

    return base64.b64encode(salt), base64.b64encode(hashed_password)

