import numpy as np
from scipy import stats

def task_func(df, column, alpha):
    try:
        alpha = float(alpha)
    except Exception:
        return False

    if not (0 < alpha < 1):
        return False

    try:
        values = np.asarray(df[column], dtype=float)
    except Exception:
        return False

    values = np.ravel(values)
    values = values[np.isfinite(values)]

    if values.size < 3:
        return False

    if np.all(values == values[0]):
        return False

    try:
        _, p_value = stats.shapiro(values)
    except Exception:
        return False

    return bool(np.isfinite(p_value) and p_value > alpha)

