import pandas as pd
from sklearn.linear_model import LinearRegression

def task_func(df, target):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if target not in df.columns:
        raise KeyError(f"target column '{target}' not found in DataFrame")

    feature_cols = [col for col in df.columns if col != target]
    if not feature_cols:
        raise ValueError("At least one predictor column is required")

    clean_df = df.dropna(subset=feature_cols + [target])
    if clean_df.empty:
        raise ValueError("No valid rows remaining after dropping missing values")

    if len(clean_df) < 2:
        raise ValueError("At least two valid rows are required to compute R-squared")

    X = clean_df[feature_cols]
    y = clean_df[target]

    try:
        X = X.apply(pd.to_numeric, errors="raise")
        y = pd.to_numeric(y, errors="raise")
    except Exception as exc:
        raise TypeError("All feature columns and the target must be numeric") from exc

    model = LinearRegression()
    model.fit(X, y)
    score = float(model.score(X, y))

    return {"score": score}

