import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    failed_files = []
    processed_count = 0
    success_count = 0

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist or is not a directory: {src_folder}",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder '{dst_folder}': {exc}",
            "failed_files": [],
        }

    # Include both normal and hidden entries; process only regular files.
    source_paths = []
    for pattern in ("*", ".*"):
        source_paths.extend(glob(os.path.join(src_folder, pattern)))

    eligible_files = []
    seen = set()
    for path in source_paths:
        if path in seen:
            continue
        seen.add(path)
        if os.path.isfile(path):
            eligible_files.append(path)

    if not eligible_files:
        return {
            "success": True,
            "message": "No regular files found to compress.",
            "failed_files": [],
        }

    for path in eligible_files:
        processed_count += 1
        filename = os.path.basename(path)

        try:
            proc = subprocess.Popen(
                ["gzip", path],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
            )
        except FileNotFoundError:
            remaining = [os.path.basename(p) for p in eligible_files[processed_count - 1:]]
            failed_files.extend(remaining)
            return {
                "success": False,
                "message": "gzip command is not available on this system.",
                "failed_files": failed_files,
            }
        except Exception:
            failed_files.append(filename)
            continue

        stdout, stderr = proc.communicate()

        if proc.returncode != 0:
            failed_files.append(filename)
            continue

        gz_path = path + ".gz"
        if not os.path.exists(gz_path):
            failed_files.append(filename)
            continue

        dest_path = os.path.join(dst_folder, os.path.basename(gz_path))
        try:
            if os.path.exists(dest_path):
                os.remove(dest_path)
            shutil.move(gz_path, dest_path)
            success_count += 1
        except Exception:
            failed_files.append(filename)
            continue

    overall_success = len(failed_files) == 0

    if overall_success:
        message = (
            f"Successfully compressed and moved {success_count} file(s) "
            f"from '{src_folder}' to '{dst_folder}'."
        )
    else:
        message = (
            f"Processed {processed_count} file(s): {success_count} succeeded, "
            f"{len(failed_files)} failed."
        )

    return {
        "success": overall_success,
        "message": message,
        "failed_files": failed_files,
    }

