import hashlib
import binascii

def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    def quote_ident(name):
        return '"' + name.replace('"', '""') + '"'

    def to_text(value):
        if value is None:
            return ""
        if isinstance(value, bytes):
            return value.decode("utf-8")
        return str(value)

    tables = [
        row[0]
        for row in cursor.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        ).fetchall()
    ]

    best = None
    best_score = None

    for table in tables:
        try:
            info = cursor.execute(f"PRAGMA table_info({quote_ident(table)})").fetchall()
        except Exception:
            continue

        password_cols = [row[1] for row in info if row[1].lower() == "password"]
        if not password_cols:
            continue

        lower_name = table.lower()
        if lower_name in ("user", "users"):
            score = (0, len(table))
        elif "user" in lower_name:
            score = (1, len(table))
        elif any(token in lower_name for token in ("account", "login", "auth")):
            score = (2, len(table))
        else:
            score = (3, len(table))

        if best is None or score < best_score:
            best = (table, info, password_cols[0])
            best_score = score

    if best is None:
        return 0

    table, info, password_col = best
    pk_cols = [row[1] for row in info if row[5]]

    updated = 0

    if pk_cols:
        select_cols = ", ".join(quote_ident(col) for col in pk_cols + [password_col])
        rows = cursor.execute(
            f"SELECT {select_cols} FROM {quote_ident(table)}"
        ).fetchall()
        where_clause = " AND ".join(f"{quote_ident(col)}=?" for col in pk_cols)

        for row in rows:
            key_vals = row[:-1]
            plain_password = to_text(row[-1])
            digest = hashlib.sha256((salt + plain_password).encode("utf-8")).digest()
            hashed = binascii.hexlify(digest).decode("ascii")
            cursor.execute(
                f"UPDATE {quote_ident(table)} SET {quote_ident(password_col)}=? WHERE {where_clause}",
                (hashed, *key_vals),
            )
            updated += 1
    else:
        try:
            rows = cursor.execute(
                f"SELECT rowid, {quote_ident(password_col)} FROM {quote_ident(table)}"
            ).fetchall()
        except Exception:
            return 0

        for rowid, password in rows:
            plain_password = to_text(password)
            digest = hashlib.sha256((salt + plain_password).encode("utf-8")).digest()
            hashed = binascii.hexlify(digest).decode("ascii")
            cursor.execute(
                f"UPDATE {quote_ident(table)} SET {quote_ident(password_col)}=? WHERE rowid=?",
                (hashed, rowid),
            )
            updated += 1

    try:
        cursor.connection.commit()
    except Exception:
        pass

    return updated

