import os
import hashlib
import json
from pathlib import Path

def task_func(directory: str) -> str:
    root = Path(directory).expanduser().resolve()
    if not root.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not root.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")

    output_path = root / "hashes.json"
    hashes = {}

    for current_dir, _, files in os.walk(root):
        current_dir_path = Path(current_dir)
        for filename in files:
            file_path = current_dir_path / filename

            # Skip the output file itself and non-regular files.
            if file_path.resolve() == output_path.resolve():
                continue
            if not file_path.is_file() or file_path.is_symlink():
                continue

            hasher = hashlib.sha256()
            with file_path.open("rb") as file_obj:
                for chunk in iter(lambda: file_obj.read(8192), b""):
                    hasher.update(chunk)

            relative_path = file_path.relative_to(root).as_posix()
            hashes[relative_path] = hasher.hexdigest()

    sorted_hashes = {path: hashes[path] for path in sorted(hashes)}
    with output_path.open("w", encoding="utf-8") as json_file:
        json.dump(sorted_hashes, json_file, indent=2, ensure_ascii=False)

    return str(output_path)

