        def _send_json_response(self, status_code, payload):
            response_body = json.dumps(payload).encode("utf-8")
            self.send_response(status_code)
            self.send_header("content-type", "application/json")
            self.send_header("content-length", str(len(response_body)))
            self.end_headers()
            self.wfile.write(response_body)

        def do_POST(self):
            content_type = (self.headers.get("Content-Type") or "").strip()
            if content_type != "application/json":
                self._send_json_response(
                    400,
                    {
                        "status": "error",
                        "message": "Content-Type header is not application/json",
                    },
                )
                return

            try:
                content_length = int(self.headers.get("Content-Length", "0"))
                if content_length < 0:
                    raise ValueError
            except (TypeError, ValueError):
                content_length = 0

            try:
                raw_body = self.rfile.read(content_length).decode("utf-8")
                parsed_body = json.loads(raw_body)
            except Exception:
                self._send_json_response(
                    400,
                    {
                        "status": "error",
                        "message": "Invalid JSON",
                    },
                )
                return

            if not isinstance(parsed_body, dict) or "data" not in parsed_body:
                self._send_json_response(
                    400,
                    {
                        "status": "error",
                        "message": "No data key in request",
                    },
                )
                return

            self._send_json_response(200, SUCCESS_RESPONSE)

        def log_message(self, format, *args):
