import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def _first_float(text):
    number = []
    started = False
    for ch in text:
        if ch.isdigit() or ch == ".":
            number.append(ch)
            started = True
        elif started:
            break
    if not number:
        return None
    try:
        return float("".join(number))
    except ValueError:
        return None


def _parse_unix_top_output(output):
    for line in output.splitlines():
        lower = line.lower()
        if "cpu" not in lower:
            continue

        for part in line.split(","):
            part_lower = part.lower()
            if "idle" in part_lower or part_lower.strip().endswith("id"):
                idle = _first_float(part)
                if idle is not None:
                    usage = 100.0 - idle
                    if usage < 0.0:
                        usage = 0.0
                    elif usage > 100.0:
                        usage = 100.0
                    return round(usage, 2)
    return 0.0


def _get_cpu_usage(system_name):
    try:
        if system_name.lower().startswith("win"):
            commands = [
                ["wmic", "cpu", "get", "loadpercentage", "/value"],
                [
                    "powershell",
                    "-NoProfile",
                    "-Command",
                    "(Get-CimInstance Win32_Processor | Measure-Object -Property LoadPercentage -Average).Average",
                ],
            ]

            for cmd in commands:
                try:
                    result = subprocess.run(
                        cmd,
                        capture_output=True,
                        text=True,
                        check=False,
                    )
                except OSError:
                    continue

                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line:
                        continue

                    if "=" in line:
                        _, value = line.split("=", 1)
                    else:
                        value = line

                    parsed = _first_float(value)
                    if parsed is not None:
                        return round(parsed, 2)

            return 0.0

        cmd = ["top", "-l", "1"] if system_name == "Darwin" else ["top", "-bn1"]
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
        return _parse_unix_top_output(result.stdout)

    except Exception:
        return 0.0


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system_name = platform.system()
    records = []

    start = time.monotonic()
    next_sample_time = start

    while True:
        now = time.monotonic()
        if now < next_sample_time:
            time.sleep(next_sample_time - now)

        records.append(
            {
                "timestamp": time.time(),
                "cpu_usage": _get_cpu_usage(system_name),
            }
        )

        next_sample_time += interval
        if time.monotonic() - start >= duration:
            break

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as file_obj:
            json.dump(records, file_obj, ensure_ascii=False, indent=2)
    except OSError:
        return None

    return LOGFILE_PATH

