from openpyxl import load_workbook

def task_func(file_name, excel_file_path, csv_file_path) -> str:
    base_name = os.path.splitext(os.path.basename(file_name or excel_file_path))[0]

    if csv_file_path:
        if csv_file_path.endswith(os.sep) or (os.altsep is not None and csv_file_path.endswith(os.altsep)):
            output_path = os.path.join(csv_file_path, base_name + ".csv")
        elif os.path.isdir(csv_file_path):
            output_path = os.path.join(csv_file_path, base_name + ".csv")
        else:
            root, _ = os.path.splitext(csv_file_path)
            output_path = root + ".csv"
    else:
        output_path = base_name + ".csv"

    def _write_csv(rows):
        with open(output_path, "w", newline="", encoding="utf-8") as csv_file:
            writer = csv.writer(csv_file)
            for row in rows:
                writer.writerow(["" if cell is None else cell for cell in row])

    if os.path.splitext(excel_file_path)[1].lower() == ".xls":
        try:
            import xlrd
        except ImportError as exc:
            raise ValueError("Reading .xls files requires the xlrd package.") from exc

        workbook = xlrd.open_workbook(excel_file_path)
        sheet_index = getattr(workbook, "active_sheet", 0)
        if not isinstance(sheet_index, int) or not (0 <= sheet_index < workbook.nsheets):
            sheet_index = 0
        worksheet = workbook.sheet_by_index(sheet_index)
        _write_csv(worksheet.row_values(row_idx) for row_idx in range(worksheet.nrows))
    else:
        workbook = load_workbook(excel_file_path, data_only=True)
        try:
            worksheet = workbook.active
            _write_csv(worksheet.iter_rows(values_only=True))
        finally:
            workbook.close()

    return os.path.basename(output_path)

