import pandas as pd
import random
from sklearn.model_selection import train_test_split

def task_func(n_data_points=10000, min_value=0.0, max_value=10.0, test_size=0.2):
    def truncate_to_3_decimals(value):
        return (int(abs(value) * 1000) / 1000.0) * (-1 if value < 0 else 1)

    values = [
        truncate_to_3_decimals(random.uniform(min_value, max_value))
        for _ in range(n_data_points)
    ]

    df = pd.DataFrame({"Value": values})

    if len(df) == 0:
        empty_df = pd.DataFrame({"Value": []})
        return empty_df.copy(), empty_df.copy()

    try:
        train_df, test_df = train_test_split(df, test_size=test_size)
    except ValueError:
        n = len(df)

        if isinstance(test_size, float):
            test_count = int(round(n * test_size))
        else:
            test_count = int(test_size)

        test_count = max(0, min(n, test_count))

        if test_count == 0:
            return df.reset_index(drop=True), df.iloc[:0].copy().reset_index(drop=True)
        if test_count == n:
            return df.iloc[:0].copy().reset_index(drop=True), df.reset_index(drop=True)

        indices = list(df.index)
        random.shuffle(indices)
        test_indices = indices[:test_count]
        test_df = df.loc[test_indices]
        train_df = df.drop(index=test_indices)

    return train_df.reset_index(drop=True), test_df.reset_index(drop=True)

